// 测试替身：fake——一个轻量但真实的实现（内存版），可跑完整链路
class FakeUserRepo {
  constructor() { this.rows = new Map(); }
  save(u) { this.rows.set(u.id, u); return u; }
  find(id) { return this.rows.get(id) ?? null; }
  count() { return this.rows.size; }
}

const repo = new FakeUserRepo();
repo.save({ id: 1, name: "mimi" });
repo.save({ id: 2, name: "kai" });
console.log(repo.find(1).name, repo.find(99), repo.count());
